import { Readable } from "node:stream";
import { Innertube, Platform, UniversalCache } from "youtubei.js";
import { StreamType } from "@discordjs/voice";

// YouTube.js requires a JS interpreter for deciphering some streaming URLs.
// This runs only code generated by YouTube.js from YouTube's player script.
if (Platform?.shim) {
  Platform.shim.eval = async (data) => new Function(data.output)();
}

let youtubePromise = null;
const resolveCache = new Map();

function textOf(value) {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (typeof value.text === "string") return value.text;
  try {
    return String(value);
  } catch {
    return "";
  }
}

function normalize(value = "") {
  return String(value)
    .toLocaleLowerCase("ru-RU")
    .replaceAll("ё", "е")
    .replace(/[^a-zа-я0-9]+/gi, " ")
    .trim();
}

function tokens(value) {
  return new Set(normalize(value).split(/\s+/).filter((item) => item.length > 1));
}

function tokenOverlap(a, b) {
  const left = tokens(a);
  const right = tokens(b);
  if (!left.size || !right.size) return 0;
  let same = 0;
  for (const token of left) if (right.has(token)) same += 1;
  return same / Math.max(left.size, right.size);
}

function getVideoDuration(video) {
  const direct = Number(video?.duration?.seconds);
  if (Number.isFinite(direct) && direct > 0) return direct;

  const text = textOf(video?.length_text);
  const parts = text.split(":").map(Number);
  if (parts.some((part) => !Number.isFinite(part))) return 0;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
}

function candidateFromVideo(video) {
  return {
    videoId: video?.video_id || video?.id || "",
    title: textOf(video?.title),
    author: video?.author?.name || textOf(video?.author) || "YouTube",
    duration: getVideoDuration(video),
    isLive: Boolean(video?.is_live),
    thumbnail: video?.best_thumbnail?.url || null,
  };
}

function scoreCandidate(candidate, track) {
  if (!candidate.videoId || candidate.isLive) return -10_000;

  const wantedTitle = normalize(track.title);
  const wantedArtist = normalize(track.artist);
  const title = normalize(candidate.title);
  const author = normalize(candidate.author);
  const all = `${title} ${author}`;

  let score = 0;
  score += tokenOverlap(candidate.title, track.title) * 90;
  score += tokenOverlap(`${candidate.title} ${candidate.author}`, track.artist) * 55;

  if (wantedTitle && title.includes(wantedTitle)) score += 45;
  if (wantedArtist && all.includes(wantedArtist)) score += 35;

  const targetDuration = Number(track.duration) || 0;
  if (targetDuration && candidate.duration) {
    const diff = Math.abs(targetDuration - candidate.duration);
    if (diff <= 3) score += 65;
    else if (diff <= 7) score += 45;
    else if (diff <= 15) score += 20;
    else if (diff <= 30) score -= 15;
    else score -= 80;
  }

  // Prefer studio/original uploads. Covers/remixes frequently have the same name.
  if (/official audio|topic|официальн|provided to youtube/i.test(`${candidate.title} ${candidate.author}`)) score += 16;
  if (/cover|кавер|nightcore|sped up|slowed|remix|ремикс|live|concert|концерт|reaction|реакц/i.test(candidate.title)) score -= 45;
  if (/karaoke|караоке|instrumental|минус/i.test(candidate.title) && !track.instrumental) score -= 55;

  return score;
}

async function getYoutube() {
  if (!youtubePromise) {
    youtubePromise = Innertube.create({
      lang: "ru",
      location: "RU",
      cache: new UniversalCache(true),
      enable_session_cache: true,
    }).catch((error) => {
      youtubePromise = null;
      throw error;
    });
  }
  return youtubePromise;
}

async function findBestCandidate(track) {
  const key = `${normalize(track.artist)}|${normalize(track.title)}|${Math.round(Number(track.duration) || 0)}`;
  const cached = resolveCache.get(key);
  if (cached && Date.now() - cached.at < 6 * 60 * 60_000) return cached.value;

  const youtube = await getYoutube();
  const query = `${track.artist} ${track.title}`.trim();
  const search = await youtube.search(query, { type: "video" });
  const videos = Array.from(search?.videos || []);

  const ranked = videos
    .slice(0, 16)
    .map(candidateFromVideo)
    .map((candidate) => ({ ...candidate, score: scoreCandidate(candidate, track) }))
    .sort((a, b) => b.score - a.score);

  const best = ranked[0];
  if (!best || best.score < -100 || !best.videoId) {
    throw new Error("AUDIO_NOT_FOUND");
  }

  resolveCache.set(key, { at: Date.now(), value: best });
  return best;
}

async function downloadWebmOpus(youtube, videoId) {
  const attempts = [
    { type: "audio", quality: "best", format: "webm", codec: "opus" },
    { type: "audio", quality: "best", format: "webm", codec: "opus", client: "ANDROID" },
  ];

  let lastError = null;
  for (const options of attempts) {
    try {
      const webStream = await youtube.download(videoId, options);
      if (!webStream) throw new Error("EMPTY_AUDIO_STREAM");
      const stream = typeof webStream.getReader === "function"
        ? Readable.fromWeb(webStream)
        : Readable.from(webStream);
      return stream;
    } catch (error) {
      lastError = error;
    }
  }

  throw new Error("AUDIO_STREAM_FAILED", { cause: lastError });
}

export async function resolveAudio(track) {
  if (!track?.title || !track?.artist) throw new Error("TRACK_INVALID");

  const youtube = await getYoutube();
  const candidate = await findBestCandidate(track);
  const stream = await downloadWebmOpus(youtube, candidate.videoId);

  return {
    stream,
    inputType: StreamType.WebmOpus,
    source: {
      provider: "youtube",
      videoId: candidate.videoId,
      title: candidate.title,
      author: candidate.author,
      duration: candidate.duration,
      thumbnail: candidate.thumbnail,
    },
  };
}
